function foundationSeeds(): Seed[] {
  const muscles = Object.values(muscleAttachments);
  const fields = ["origin", "insertion", "action", "innervation"] as const;
  const prompts: Record<typeof fields[number], Pair> = {
    origin: pair("Quel ensemble décrit les origines habituelles de ce muscle ?", "Which set describes this muscle’s usual origins?"),
    insertion: pair("Quelle description correspond à l’insertion de ce muscle ?", "Which description matches this muscle’s insertion?"),
    action: pair("Quelle description résume les actions de ce muscle ?", "Which description summarises this muscle’s actions?"),
    innervation: pair("Quelle innervation motrice correspond à ce muscle ?", "Which motor innervation matches this muscle?"),
  };
  return muscles.flatMap((muscle, index) => fields.map((field): Seed => {
    const value = muscle[field];
    const others = [1, 2, 3].map((offset) => {
      const other = muscles[(index + offset) % muscles.length]![field];
      return pair(other.fr, other.en);
    }) as [Pair, Pair, Pair];
    return q(muscle.id, `foundation-${field}`, field, 1,
      pair(`${muscle.name.fr} — ${prompts[field][0]}`, `${muscle.name.en} — ${prompts[field][1]}`),
      pair(value.fr, value.en), others, pair(value.fr, value.en));
  }));
}

export type MuscleQuestion = Question & { anatomyFocus: AnatomyFocus };
export const muscleQuestionSeeds: Seed[] = [...foundationSeeds(), ...muscleDetailSeeds];

export function buildMuscleQuestions(language: AnatomyLanguage): MuscleQuestion[] {
  const languageIndex = language === "fr" ? 0 : 1;
  return muscleQuestionSeeds.map((seed, index) => {
    const muscle = muscleAttachments[seed.muscle];
    if (!muscle) throw new Error(`Unknown muscle reference: ${seed.muscle}`);
    const choices = [seed.answer, ...seed.others];
    const offset = index % 4;
    const ordered = [...choices.slice(offset), ...choices.slice(0, offset)];
    const reason = seed.reason[languageIndex];
    const minimumYear = seed.level === 3 ? 5 : seed.level === 2 ? 2 : 1;
    return {
      id: `anatomie-muscle-${seed.muscle}-${seed.id}`,
      version: 1,
      specialty: "anatomie",
      anatomyFocus: seed.focus,
      theme: anatomyFocusLabels[seed.focus][language],
      difficulty: seed.level === 3 ? "avancé" : seed.level === 2 ? "intermédiaire" : "débutant",
      type: "visuel",
      objective: language === "fr" ? `Relier ${muscle.name.fr.toLowerCase()} et ${anatomyFocusLabels[seed.focus].fr.toLowerCase()}.` : `Connect ${muscle.name.en.toLowerCase()} with its ${anatomyFocusLabels[seed.focus].en.toLowerCase()}.`,
      title: seed.prompt[languageIndex],
      context: language === "fr"
        ? `Structure étudiée : ${muscle.name.fr}. Le schéma situe le muscle dans son ensemble ; les chefs, attaches et petits reliefs ne sont pas représentés à l’échelle.`
        : `Structure studied: ${muscle.name.en}. The diagram locates the whole muscle; heads, attachments and small landmarks are not drawn to scale.`,
      clues: language === "fr" ? ["Repérer le muscle dans son ensemble", "Raisonner en position anatomique"] : ["Locate the whole muscle", "Reason in anatomical position"],
      options: ordered.map((choice) => ({
        label: choice[languageIndex],
        explanation: choice === seed.answer ? reason : (language === "fr" ? "Cette proposition ne répond pas au repère ou au mouvement demandé. " : "This option does not match the landmark or movement asked about. ") + reason,
      })),
      correct: ordered.indexOf(seed.answer),
      reasoning: reason,
      takeaway: reason,
      sources: muscle.sources.map((source) => ({ ...source })),
      editorialDate: "2026-10-21",
      status: "demo",
      medicalReviewer: null,
      studyYears: Array.from({ length: 13 - minimumYear }, (_, year) => minimumYear + year),
      diagram: { structureId: seed.muscle, view: seed.muscle === "triceps" ? "back" : "front" },
    };
  });
}

export const muscleQuestions = buildMuscleQuestions("fr");
